import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df_counted = df[df['row_kind'] == 'counted'].copy()

    # Attrition rate by department using pre-computed average headcounts
    avg_hc_by_dept = {
        'Engineering': 410.1,
        'Marketing': 145.9,
        'Sales': 345.8,
        'Finance': 141.9,
        'Support': 267.5,
    }

    dept_exits = {}
    for dept in avg_hc_by_dept:
        dept_df = df_counted[df_counted['department'] == dept]
        exits = dept_df['exit_event_date'].notna().sum()
        dept_exits[dept] = exits

    attrition_rates = {}
    for dept, avg_hc in avg_hc_by_dept.items():
        exits = dept_exits.get(dept, 0)
        rate = exits / avg_hc if avg_hc > 0 else 0.0
        attrition_rates[dept] = rate

    attrition_results = [
        {"name": dept, "value": round(rate, 4)}
        for dept, rate in sorted(attrition_rates.items(), key=lambda x: -x[1])
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": attrition_results
