import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df_counted = df[df['row_kind'] == 'counted'].copy()

    dept_avg_hc = {
        'Engineering': 410.1,
        'Marketing': 145.9,
        'Sales': 345.8,
        'Finance': 141.9,
        'Support': 267.5,
    }

    dept_exits = (
        df_counted[df_counted['exit_event_date'].notna()]
        .groupby('department')['employee_id']
        .count()
        .reset_index()
        .rename(columns={'employee_id': 'separations'})
    )

    dept_exits['avg_hc'] = dept_exits['department'].map(dept_avg_hc)
    dept_exits['attrition_rate'] = dept_exits['separations'] / dept_exits['avg_hc']

    dept_exits_sorted = dept_exits.sort_values('attrition_rate', ascending=False)

    attrition_results = [
        {"name": row['department'], "value": round(row['attrition_rate'], 4)}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": attrition_results,
    })

    sep_results = [
        {"name": row['department'], "value": float(row['separations'])}
        for _, row in dept_exits_sorted.iterrows()
    ]

    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_count",
        "results": sep_results,
    })

    result['assumptions'].append(
        "Attrition rate = separations (exit_event_date in window) / avg headcount per department (provided facts)."
    )
    result['assumptions'].append(
        "Only 'counted' rows used; contractors/agency workers excluded per domain rules."
    )
    result['assumptions'].append(
        "All separations counted (voluntary + involuntary + retirement) as question names no specific kind."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": [{"name": f"error: {str(e)}", "value": 0.0}],
    })

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
