try:
    import numpy as np

    # Pay gap definition: (men's avg pay - women's avg pay) / men's avg pay
    # On FTE-adjusted pay (salary / FTE), people in force at latest date, contractors out
    # By Job_Level, groups < 11 not shown

    # Filter: counted rows only, exclude contractors/agency
    df_counted = df[df['row_kind'] == 'counted'].copy()

    # Exclude contractors and agency workers
    exclude_types = ['Contractor', 'Agency', 'Consultant', 'contractor', 'agency', 'consultant']
    df_counted = df_counted[~df_counted['Worker_Type'].str.lower().isin(
        ['contractor', 'agency', 'consultant']
    )]

    # People in force at latest date (31 Oct 2026):
    # Hired on or before 31 Oct 2026, termination blank or after 31 Oct 2026
    latest_date = pd.Timestamp('2026-10-31')
    df_counted['Hire_Date_dt'] = pd.to_datetime(df_counted['Hire_Date'], errors='coerce')
    df_counted['Term_Date_dt'] = pd.to_datetime(df_counted['Termination_Date'], errors='coerce')

    in_force = df_counted[
        (df_counted['Hire_Date_dt'] <= latest_date) &
        (df_counted['Term_Date_dt'].isna() | (df_counted['Term_Date_dt'] > latest_date))
    ].copy()

    # Deduplicate by Employee_ID (distinct people)
    in_force = in_force.drop_duplicates(subset='Employee_ID')

    # Compute FTE-adjusted pay
    in_force['fte_pay'] = in_force['Annual_Salary'] / in_force['FTE'].replace(0, np.nan)

    # Filter to Male and Female only (non-binary excluded from gap calc)
    in_force_gendered = in_force[in_force['Gender'].isin(['Male', 'Female'])].copy()

    job_levels = in_force_gendered['Job_Level'].dropna().unique()

    gap_results_mean = []
    gap_results_median = []

    for lvl in sorted(job_levels):
        lvl_df = in_force_gendered[in_force_gendered['Job_Level'] == lvl]
        men = lvl_df[lvl_df['Gender'] == 'Male']['fte_pay'].dropna()
        women = lvl_df[lvl_df['Gender'] == 'Female']['fte_pay'].dropna()
        if len(men) < 11 or len(women) < 11:
            continue
        men_mean = men.mean()
        women_mean = women.mean()
        men_median = men.median()
        women_median = women.median()
        gap_mean = (men_mean - women_mean) / men_mean if men_mean != 0 else np.nan
        gap_median = (men_median - women_median) / men_median if men_median != 0 else np.nan
        gap_results_mean.append({"name": str(lvl), "value": round(float(gap_mean), 4)})
        gap_results_median.append({"name": str(lvl), "value": round(float(gap_median), 4)})

    # Overall pay gap (all levels combined, groups >= 11)
    men_all = in_force_gendered[in_force_gendered['Gender'] == 'Male']['fte_pay'].dropna()
    women_all = in_force_gendered[in_force_gendered['Gender'] == 'Female']['fte_pay'].dropna()
    if len(men_all) >= 11 and len(women_all) >= 11:
        overall_gap_mean = (men_all.mean() - women_all.mean()) / men_all.mean()
