try:
    from scipy import stats
    tests = []

    left_0 = df.loc[df['left'] == 0, 'salary'].dropna()
    left_1 = df.loc[df['left'] == 1, 'salary'].dropna()
    t_stat, p_val = stats.ttest_ind(left_0, left_1, equal_var=False)
    t_stat = float(t_stat)
    p_val = float(p_val)
    mean0 = float(left_0.mean())
    mean1 = float(left_1.mean())
    interp = (
        f"Welch t-test: t={t_stat:.3f}, p={p_val:.3g}. "
        f"Mean salary stayed={mean0:.1f}, left={mean1:.1f}. "
        + ("Significant difference in salary between leavers and stayers." if p_val < 0.05
           else "No significant difference in salary between leavers and stayers.")
    )
    tests.append({
        "test_name": "Welch t-test: salary by left (0 vs 1)",
        "statistic": round(t_stat, 4),
        "p_value": round(p_val, 6),
        "interpretation": interp
    })

    left_0_perf = df.loc[df['left'] == 0, 'performance_score'].dropna()
    left_1_perf = df.loc[df['left'] == 1, 'performance_score'].dropna()
    t2, p2 = stats.ttest_ind(left_0_perf, left_1_perf, equal_var=False)
    t2 = float(t2)
    p2 = float(p2)
    m0p = float(left_0_perf.mean())
    m1p = float(left_1_perf.mean())
    interp2 = (
        f"Welch t-test: t={t2:.3f}, p={p2:.3g}. "
        f"Mean performance stayed={m0p:.3f}, left={m1p:.3f}. "
        + ("Significant difference in performance score between leavers and stayers." if p2 < 0.05
           else "No significant difference in performance score between leavers and stayers.")
    )
    tests.append({
