        "statistic": round(t2, 4),
        "p_value": round(p2, 6),
        "interpretation": interp2
    })

    left_0_ten = df.loc[df['left'] == 0, 'tenure_months'].dropna()
    left_1_ten = df.loc[df['left'] == 1, 'tenure_months'].dropna()
    t3, p3 = stats.ttest_ind(left_0_ten, left_1_ten, equal_var=False)
    t3 = float(t3)
    p3 = float(p3)
    m0t = float(left_0_ten.mean())
    m1t = float(left_1_ten.mean())
    interp3 = (
        f"Welch t-test: t={t3:.3f}, p={p3:.3g}. "
        f"Mean tenure stayed={m0t:.3f}, left={m1t:.3f}. "
        + ("Significant difference in tenure between leavers and stayers." if p3 < 0.05
