    )
    tests.append({
        "test_name": "Welch t-test: tenure_months by left (0 vs 1)",
        "statistic": round(t3, 4),
        "p_value": round(p3, 6),
        "interpretation": interp3
    })

    dept_left = df.groupby('department')['left'].agg(['sum', 'count'])
    dept_left['stayed'] = dept_left['count'] - dept_left['sum']
    contingency = dept_left[['sum', 'stayed']].values
    chi2, p_chi, dof, _ = stats.chi2_contingency(contingency)
    chi2 = float(chi2)
    p_chi = float(p_chi)
    interp4 = (
        f"Chi-square test of independence (department vs left): "
        f"chi2={chi2:.3f}, dof={dof}, p={p_chi:.3g}. "
        + ("Attrition rate differs significantly across departments." if p_chi < 0.05
           else "No significant association between department and attrition.")
    )
    tests.append({
        "test_name": "Chi-square: department vs left",
        "statistic": round(chi2, 4),
        "p_value": round(p_chi, 6),
        "interpretation": interp4
    })

    result['statistical_tests'] = tests
except Exception:
    pass

result['assumptions'] = [
    "Pearson r measures linear association only; salary-attrition relationship may be non-linear.",
