        df.loc[df['left'] == 0, 'performance_score'].dropna(),
        df.loc[df['left'] == 1, 'performance_score'].dropna(),
        equal_var=False
    )
    perf_stat = float(round(perf_stat, 4))
    perf_p = float(round(perf_p, 6))
    mean_perf_stayed = float(round(df.loc[df['left'] == 0, 'performance_score'].mean(), 4))
    mean_perf_left = float(round(df.loc[df['left'] == 1, 'performance_score'].mean(), 4))
    interp_perf = (
        f"Welch t-test: t={perf_stat}, p={perf_p}. "
        f"Mean performance stayed={mean_perf_stayed}, left={mean_perf_left}. "
        + ("Significant difference in performance score between leavers and stayers."
           if perf_p < 0.05 else "No significant difference in performance score between leavers and stayers.")
    )
    tests.append({
        "test_name": "Welch t-test: performance_score by left (0 vs 1)",
        "statistic": perf_stat,
        "p_value": perf_p,
        "interpretation": interp_perf
    })

    tenure_stat, tenure_p = sp_stats.ttest_ind(
        df.loc[df['left'] == 0, 'tenure_months'].dropna(),
        df.loc[df['left'] == 1, 'tenure_months'].dropna(),
        equal_var=False
    )
    tenure_stat = float(round(tenure_stat, 4))
    tenure_p = float(round(tenure_p, 6))
    mean_tenure_stayed = float(round(df.loc[df['left'] == 0, 'tenure_months'].mean(), 4))
    mean_tenure_left = float(round(df.loc[df['left'] == 1, 'tenure_months'].mean(), 4))
    interp_tenure = (
        f"Welch t-test: t={tenure_stat}, p={tenure_p}. "
        f"Mean tenure stayed={mean_tenure_stayed}, left={mean_tenure_left}. "
        + ("Significant difference in tenure between leavers and stayers."
           if tenure_p < 0.05 else "No significant difference in tenure between leavers and stayers.")
    )
    tests.append({
        "test_name": "Welch t-test: tenure_months by left (0 vs 1)",
        "statistic": tenure_stat,
        "p_value": tenure_p,
        "interpretation": interp_tenure
    })

    dept_left = df.groupby('department')['left'].sum()
    dept_total = df.groupby('department')['left'].count()
    dept_not_left = dept_total - dept_left
    contingency = np.column_stack([dept_left.values, dept_not_left.values])
    chi2, chi_p, dof, _ = sp_stats.chi2_contingency(contingency)
    chi2 = float(round(chi2, 4))
    chi_p = float(round(chi_p, 6))
    dof = int(dof)
    interp_chi = (
        f"Chi-square test of attrition by department: chi2={chi2}, dof={dof}, p={chi_p}. "
        + ("Attrition rate differs significantly across departments."
           if chi_p < 0.05 else "No significant difference in attrition rate across departments.")
    )
    tests.append({
        "test_name": "Chi-square: attrition by department",
        "statistic": chi2,
        "p_value": chi_p,
        "interpretation": interp_chi
    })

    result['statistical_tests'] = tests
except Exception as e:
    result['assumptions'].append(f"Hypothesis test error: {e}")

result['assumptions'] = [
