        df["exit_event_date"].notna()
        & (df["exit_event_date"] >= window_start)
        & (df["exit_event_date"] <= window_end)
        & (~df["Worker_Type"].isin(["Contractor", "Agency", "Consultant"]))
        & (df["row_kind"] == "counted")
    ].copy()

