result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    df['Hire_Date'] = pd.to_datetime(df['Hire_Date'], errors='coerce')
    df['Termination_Date'] = pd.to_datetime(df['Termination_Date'], errors='coerce')
    df['exit_event_date'] = pd.to_datetime(df['exit_event_date'], errors='coerce') if 'exit_event_date' in df.columns else pd.NaT
    df['hire_event_date'] = pd.to_datetime(df['hire_event_date'], errors='coerce') if 'hire_event_date' in df.columns else pd.NaT

    counted = df[df['row_kind'] == 'counted'] if 'row_kind' in df.columns else df

    non_contractor = counted[~counted['Worker_Type'].isin(['Contractor', 'Agency', 'Consultant'])]

    exits_2025 = non_contractor[
        (non_contractor['exit_event_date'] >= '2025-01-01') &
        (non_contractor['exit_event_date'] <= '2025-12-31')
    ]
    exits_2026 = non_contractor[
        (non_contractor['exit_event_date'] >= '2026-01-01') &
        (non_contractor['exit_event_date'] <= '2026-10-31')
    ]

    sep_2025 = len(exits_2025)
    sep_2026 = len(exits_2026)

    hc_2025_monthly = [885, 901, 918, 934, 945, 1009, 1000, 1002, 997, 994, 999, 996]
    avg_hc_2025 = round(np.mean(hc_2025_monthly), 1)

    avg_hc_2026_partial = 965.0

    attrition_2025 = round(sep_2025 / avg_hc_2025, 4) if avg_hc_2025 > 0 else 0.0
    attrition_2026 = round(sep_2026 / avg_hc_2026_partial, 4) if avg_hc_2026_partial > 0 else 0.0

    result['segments'].append({
        "segment_column": "Employment_Status",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate_by_year",
        "results": [
            {"name": "2025 (Jan–Dec, full year)", "value": attrition_2025},
            {"name": "2026 (Jan–Oct, partial year)", "value": attrition_2026},
            {"name": "2025 separations", "value": float(sep_2025)},
            {"name": "2026 separations (Jan–Oct)", "value": float(sep_2026)},
            {"name": "2025 avg headcount", "value": float(avg_hc_2025)},
            {"name": "2026 avg headcount (Nov2025–Oct2026)", "value": float(avg_hc_2026_partial)},
        ]
    })

    dept_col = 'Department'
    dept_avg_hc_2026 = {'Sales': 213.0, 'Operations': 118.2, 'Support': 183.2,
                        'Engineering': 271.1, 'Marketing': 96.6, 'Finance': 76.9, 'Legal': 6.0}

    dept_sep_2025 = exits_2025.groupby(dept_col).size()
    dept_sep_2026 = exits_2026.groupby(dept_col).size()

    dept_results_2025 = []
    dept_results_2026 = []
    for dept in dept_avg_hc_2026.keys():
        s25 = dept_sep_2025.get(dept, 0)
        s26 = dept_sep_2026.get(dept, 0)
        hc26 = dept_avg_hc_2026[dept]
        dept_results_2025.append({"name": dept, "value": round(s25 / avg_hc_2025 * (hc26 / avg_hc_2026_partial), 4)})
        dept_results_2026.append({"name": dept, "value": round(s26 / hc26, 4) if hc26 > 0 else 0.0})

    dept_sep_2025_raw = [{"name": dept, "value": float(dept_sep_2025.get(dept, 0))} for dept in dept_avg_hc_2026.keys()]
    dept_sep_2026_raw = [{"name": dept, "value": float(dept_sep_2026.get(dept, 0))} for dept in dept_avg_hc_2026.keys()]

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_2025_by_department",
        "results": dept_sep_2025_raw
    })

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_2026_jan_oct_by_department",
        "results": dept_sep_2026_raw
    })

    result['segments'].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate_2026_jan_oct_by_department",
        "results": dept_results_2026
    })

    jl_avg_hc_2026 = {'L1': 302.5, 'L2': 285.5, 'L3': 185.2, 'L4': 131.7, 'L5': 60.1}
    jl_sep_2025 = exits_2025.groupby('Job_Level').size()
    jl_sep_2026 = exits_2026.groupby('Job_Level').size()

    jl_sep_2025_raw = [{"name": jl, "value": float(jl_sep_2025.get(jl, 0))} for jl in jl_avg_hc_2026.keys()]
    jl_sep_2026_raw = [{"name": jl, "value": float(jl_sep_2026.get(jl, 0))} for jl in jl_avg_hc_2026.keys()]
    jl_rate_2026 = [{"name": jl, "value": round(jl_sep_2026.get(jl, 0) / hc, 4) if hc > 0 else 0.0}
                    for jl, hc in jl_avg_hc_2026.items()]

    result['segments'].append({
        "segment_column": "Job_Level",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_2025_by_job_level",
        "results": jl_sep_2025_raw
    })
    result['segments'].append({
        "segment_column": "Job_Level",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_2026_jan_oct_by_job_level",
        "results": jl_sep_2026_raw
    })
    result['segments'].append({
        "segment_column": "Job_Level",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate_2026_jan_oct_by_job_level",
        "results": jl_rate_2026
    })

    result['assumptions'].append("2025 avg headcount estimated from the 12 month-end values Nov2025–Oct2026 reversed: used the provided monthly headcounts in reverse order as a proxy for 2025 calendar year.")
    result['assumptions'].append("2026 attrition covers Jan–Oct 2026 only (partial year, 10 months); not annualised.")
    result['assumptions'].append("Contractors, Agency workers and Consultants excluded from all attrition counts.")
    result['assumptions'].append("Department attrition rates for 2026 use the provided average headcounts (Nov2025–Oct2026 window).")
    result['assumptions'].append("5 hire/exit dates after 31 Oct 2026 are excluded per domain rules.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

