import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Window: 1 Nov 2025 – 31 Oct 2026
    window_start = pd.Timestamp("2025-11-01")
    window_end = pd.Timestamp("2026-10-31")

    # Average headcount by department (from domain facts)
    avg_hc_dept = {
        "Support": 56.2,
        "Sales": 95.2,
        "Marketing": 37.7,
        "Finance": 28.2,
        "Engineering": 82.6,
        "Operations": 43.1,
    }

    # Exits: rows with exit_event_date in the window, row_kind == 'counted'
    exits_df = df[
        (df["row_kind"] == "counted") &
        (df["exit_event_date"].notna()) &
        (pd.to_datetime(df["exit_event_date"]) >= window_start) &
        (pd.to_datetime(df["exit_event_date"]) <= window_end)
    ].copy()

    # Count separations by department (where person left from)
    sep_by_dept = exits_df.groupby("Department")["Emp_ID"].count().reset_index()
    sep_by_dept.columns = ["Department", "separations"]

    # Compute attrition rate per department
    dept_results = []
    for _, row in sep_by_dept.iterrows():
        dept = row["Department"]
        seps = int(row["separations"])
        avg_hc = avg_hc_dept.get(dept, None)
        if avg_hc and avg_hc > 0:
            rate = round(seps / avg_hc, 4)
            dept_results.append({"name": dept, "value": rate})

    # Also add departments with zero exits
    for dept, avg_hc in avg_hc_dept.items():
        if dept not in sep_by_dept["Department"].values:
            dept_results.append({"name": dept, "value": 0.0})

    # Sort by attrition rate descending
    dept_results.sort(key=lambda x: x["value"], reverse=True)

    # Overall attrition rate
    total_seps = int(exits_df["Emp_ID"].count())
    overall_avg_hc = 343.1
    overall_rate = round(total_seps / overall_avg_hc, 4)

    result["segments"].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "attrition_rate",
        "results": dept_results
    })

    result["segments"].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "count",
        "label": "separations_count",
        "results": [
            {"name": r["Department"], "value": float(r["separations"])}
            for _, r in sep_by_dept.iterrows()
        ]
    })

    result["segments"].append({
        "segment_column": "Department",
        "metric_column": "exit_event_date",
        "aggregation": "ratio",
        "label": "overall_attrition_rate",
        "results": [{"name": "Overall", "value": overall_rate}]
    })

    result["assumptions"].append(
        "Attrition rate = separations (exit_event_date in Nov 2025–Oct 2026) ÷ average headcount from domain facts."
    )
    result["assumptions"].append(
        "Only row_kind='counted' rows used; contractors/agency excluded per domain rules."
    )
    result["assumptions"].append(
        f"Total separations in window: {total_seps}; overall average headcount: {overall_avg_hc}; overall rate: {overall_rate:.4f}."
    )

except Exception as e:
    result["assumptions"].append(f"Segmentation error: {str(e)}")

